function anaView(view,box,hl,label){
  const A=ANA[view], ids=Object.keys(A.m);
  const order=ids.filter(i=>!hl.includes(i)).concat(ids.filter(i=>hl.includes(i)));
  const shapes=order.map(id=>A.m[id].map(d=>`<path class="mu${hl.includes(id)?' hl':''}" d="${d}"/>`).join('')).join('');
  const body=A.mir?`<path class="sil" d="${A.sil}"/>${shapes}<g transform="matrix(-1 0 0 1 200 0)">${shapes}</g>`:`<path class="sil" d="${A.sil}"/>${shapes}`;
  return `<svg class="an" viewBox="${box}" role="img" aria-label="${label}">${body}</svg>`;
}
function ana(c){const v=VW[c]; return v?anaView(v[0],v[1],v[2],M[c][0]+' highlighted'):'';}
