const mkEx=(r,i)=>{
  const [g,n,a,k,mach,lat,b,ms]=r;
  const raw=ms.split(',').map(t=>{const m=/^([A-Z]+)(\d+)([PS])$/.exec(t);return {c:m[1],p:+m[2],r:m[3]};});
  const rk=(x,y)=>(y.p-x.p)||((x.r==='P'?0:1)-(y.r==='P'?0:1));
  const full=raw.slice().sort((x,y)=>(x.r===y.r?0:(x.r==='P'?-1:1))||y.p-x.p);
  let u=raw.map(x=>({...x}));
  [["BIC",HEADS.BIC],["TRI",HEADS.TRI]].forEach(([f,hs])=>{
    const mem=u.filter(x=>hs.includes(x.c)); if(!mem.length) return;
    if(Math.max(...mem.map(x=>x.p))>=25) return;
    const sum=mem.reduce((s,x)=>s+x.p,0);
    u=u.filter(x=>!hs.includes(x.c)); u.push({c:f,p:sum,r:mem.some(x=>x.r==='P')?'P':'S'});
  });
  u.sort(rk);
  let top=u.slice(0,2); if(u[2]&&u[2].p>=12) top.push(u[2]);
  const tot=top.reduce((s,x)=>s+x.p,0); let acc=0;
  top=top.map((x,j)=>{const v=j===top.length-1?100-acc:Math.round(x.p/tot*100);acc+=v;return {c:x.c,p:v,r:x.r};});
  const tags=[u[0].c]; if(u[1]&&u[1].p>=0.85*u[0].p) tags.push(u[1].c);
  const rawOf=c=>{ if(HEADS[c]&&c!=='QUA') return raw.filter(x=>HEADS[c].includes(x.c)).reduce((s,x)=>s+x.p,0); if(c==='QUA') return raw.filter(x=>HEADS.QUA.includes(x.c)).reduce((s,x)=>s+x.p,0); const f=raw.find(x=>x.c===c); return f?f.p:0; };
  const hay=[n,a,g,TRK[g+'|'+n]||'',mach,KEYS[k][0],CATS[CAT[k]]].concat(raw.map(x=>M[x.c][0]+' '+M[x.c][1])).concat(tags.map(t=>M[t][0])).join(' ').toLowerCase();
  return {i,g,n,a,trk:TRK[g+'|'+n]||'',k,mach,lat,b,full,top,tags,rawOf,hay,region:GROUP_REGION[g]};
};
const EX=D.map(mkEx);


