function secOf(e,list){
  const byG=list.find(s=>s.g&&s.g.includes(e.g)); if(byG) return byG;
  let best=null,bs=-1;
  list.forEach(s=>{ if(!s.m) return; const sc=Math.max(...s.m.map(c=>e.rawOf(c))); if(sc>bs){bs=sc;best=s;} });
  return best||list[0];
}
function chipTest(sec,code){
  if(sec.t==='Biceps') return e=>{const s=e.rawOf('BSH'),l=e.rawOf('BLH'); if(s+l===0) return false; const r=s/(s+l); return code==='SH'?r>0.6:code==='LH'?r<0.4:(r>=0.4&&r<=0.6);};
  const codes=sec.f.map(x=>x[0]);
  return e=>{const mx=Math.max(...codes.map(c=>e.rawOf(c))); return mx>0&&e.rawOf(code)>=0.85*mx;};
}


